#include "Production/AetherProductionService.h"
bool FAetherProductionService::Initialize(const FAetherProductionConfig&C,double Now){if(!C.IsValid())return false;Config=C;State=EAetherProductionState::Starting;Checks.Reset();Metrics.Reset();Events.Reset();StartedAt=Now;DrainStartedAt=0.;for(uint8 I=0;I<=static_cast<uint8>(EAetherProductionCheck::Content);++I)Checks.Add(static_cast<EAetherProductionCheck>(I),false);return true;}
void FAetherProductionService::Shutdown(double Now){State=EAetherProductionState::Stopped;RecordEvent(TEXT("shutdown"),TEXT("graceful shutdown completed"),false,Now);}
void FAetherProductionService::BeginDrain(double Now){if(State==EAetherProductionState::Stopped)return;State=EAetherProductionState::Draining;DrainStartedAt=Now;RecordEvent(TEXT("drain_started"),TEXT("admission should stop"),false,Now);}
bool FAetherProductionService::SetCheck(EAetherProductionCheck Check,bool bPass){if(State==EAetherProductionState::Stopped)return false;Checks.FindOrAdd(Check)=bPass;if(State==EAetherProductionState::Draining)return true;bool All=true;for(const auto&Pair:Checks)All&=Pair.Value;State=All?EAetherProductionState::Ready:EAetherProductionState::Degraded;return true;}
void FAetherProductionService::RecordMetric(const FString&Name,double Value,double Now){if(Name.TrimStartAndEnd().IsEmpty()||!FMath::IsFinite(Value))return;FAetherProductionMetric M;M.Name=Name;M.Value=Value;M.Timestamp=Now;Metrics.Add(M);if(Metrics.Num()>Config.MaxAuditEvents)Metrics.RemoveAt(0);}
void FAetherProductionService::RecordEvent(const FString&Name,const FString&Details,bool bError,double Now){if(Name.TrimStartAndEnd().IsEmpty())return;FAetherProductionAuditEvent E;E.EventName=Name;E.Details=Details;E.bError=bError;E.Timestamp=Now;Events.Add(E);if(Events.Num()>Config.MaxAuditEvents)Events.RemoveAt(0);}
FAetherProductionHealth FAetherProductionService::GetHealth(double Now)const{FAetherProductionHealth H;H.State=State;H.bLiveness=State!=EAetherProductionState::Stopped;H.bReadiness=State==EAetherProductionState::Ready;H.Checks=Checks;H.Timestamp=Now;return H;}
